<script lang="ts">
 import {onMount} from "svelte";import type {Project,Service} from "./model";import {unitLabel} from "./model";import {translator} from "./i18n";import {Plus,LayoutGrid,List,Layers3,ReceiptText,Pencil,Search} from "@lucide/svelte";
 export let project:Project;export let onedit:(service?:Service)=>void;export let ontariffs:(id:string)=>void;
 let tiles=false,query="",activeOnly=false;
 onMount(()=>tiles=localStorage.getItem("openhau-services-view")==="tiles");
 $: t=translator(project.settings.language);
 $: rows=project.services.filter(s=>(!activeOnly||s.active)&&s.name[project.settings.language].toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 function view(){tiles=!tiles;localStorage.setItem("openhau-services-view",tiles?"tiles":"list");}
 function basis(s:Service){return s.calculation_type==="metered"?t("По счётчику","După contor"):s.calculation_type==="person"?t("За человека","Pe persoană"):s.calculation_type==="area"?t("По площади","Pe suprafață"):s.calculation_type==="manual"?t("Ручной объём","Volum manual"):t("За счёт","Pe cont");}
</script>
<div class="service-catalog">
 <div class="services-toolbar"><button class="button" onclick={()=>onedit()}><Plus size={17}/>{t("Добавить","Adaugă")}</button><label class="catalog-search"><Search size={16}/><input aria-label={t("Поиск услуги","Căutare serviciu")} placeholder={t("Поиск","Căutare")} bind:value={query}/></label><button class="button secondary" aria-pressed={tiles} onclick={view}>{#if tiles}<List size={17}/>{:else}<LayoutGrid size={17}/>{/if}{t("Вид","Vizualizare")} · {tiles?t("Плитки","Dale"):t("Список","Listă")}</button><label class="check-row"><input type="checkbox" bind:checked={activeOnly}/>{t("Только активные","Doar active")}</label></div>
 {#if tiles}<div class="catalog-tiles">{#each rows as s}<button class="service-tile" onclick={()=>onedit(s)}><Layers3 size={32}/><strong>{s.name[project.settings.language]}</strong><span>{basis(s)} · {unitLabel(s.unit,project.settings.language)}</span><small>{s.active?t("Активна","Activ"):t("Отключена","Dezactivat")}</small></button>{/each}</div>{:else}<div class="table-wrap"><table><thead><tr><th>{t("Наименование","Denumire")}</th><th>{t("Основание расчёта","Baza de calcul")}</th><th>{t("Единица","Unitate")}</th><th>{t("Приборы учёта","Contoare")}</th><th>{t("Статус","Stare")}</th><th>{t("Действия","Acțiuni")}</th></tr></thead><tbody>{#each rows as s}<tr><td><button class="service-name" onclick={()=>onedit(s)}><Layers3 size={17}/>{s.name[project.settings.language]}</button></td><td>{basis(s)}</td><td>{unitLabel(s.unit,project.settings.language)}</td><td>{project.meters.filter(m=>m.service_id===s.id).length}</td><td>{s.active?t("Активна","Activ"):t("Отключена","Dezactivat")}</td><td><div class="catalog-actions"><button class="icon-button" title={t("Изменить услугу","Modifică serviciul")} aria-label={t("Изменить услугу","Modifică serviciul")} onclick={()=>onedit(s)}><Pencil size={17}/></button><button class="button secondary small" onclick={()=>ontariffs(s.id)}><ReceiptText size={16}/>{t("Тарифы","Tarife")}</button></div></td></tr>{/each}</tbody></table></div>{/if}
 {#if !rows.length}<p>{t("Услуги не найдены","Servicii negăsite")}</p>{/if}
</div>
<style>
 .service-catalog{display:flex;flex-direction:column;gap:20px}.services-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.catalog-search{display:flex;gap:8px;align-items:center;flex:1;min-width:160px}.catalog-search input{width:100%}.catalog-actions{display:flex;align-items:center;gap:12px}.service-name{display:flex;align-items:center;gap:12px;padding:10px;background:transparent;border:0;text-align:left;color:var(--text)}
 .catalog-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(175px,1fr));gap:22px;padding:8px}.service-tile{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;aspect-ratio:1;padding:20px;background:transparent;border:0;color:var(--text);text-align:center}.service-tile :global(svg){color:var(--accent)}.service-tile:hover{background:var(--hover);box-shadow:inset 0 0 0 1px var(--reveal-ink,#00000024)}.service-tile strong{font-size:14px}.service-tile span,.service-tile small{color:var(--muted)}
</style>
